import{_ as e,a as o,b as a,c as i,d as s,e as n}from"./chunks/AS-Apps-SA.CzVlwi0n.js";import{_ as r,o as l,c as p,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Android Settings","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshoot/savings.md","filePath":"troubleshoot/savings.md"}'),h={name:"troubleshoot/savings.md"};function m(g,t,u,c,b,y){return l(),p("div",null,[...t[0]||(t[0]=[d('<p>Android offers many energy savings options. Whilst they are helpful to gain more battery autonomy, they can easily target functions that are mandatory for a CGM system.</p><p>All settings described below will be available in your phone&#39;s Android settings; appearance will vary greatly and depend on the phone vendor customizations.</p><img src="'+e+'" style="zoom:75%;"><h2 id="battery-saver" tabindex="-1">Battery Saver <a class="header-anchor" href="#battery-saver" aria-label="Permalink to &quot;Battery Saver&quot;">​</a></h2><p>Whenever going below a certain battery level, Android will shut down many services and prevent xDrip from functioning normally. Make sure you always keep a power bank with you to avoid this situation.</p><p>During normal phone use, make sure it is <strong>not</strong> enabled.</p><img src="'+o+'" style="zoom:75%;"><h2 id="apps-battery-savings" tabindex="-1">Apps battery savings <a class="header-anchor" href="#apps-battery-savings" aria-label="Permalink to &quot;Apps battery savings&quot;">​</a></h2><p>Each phone app can be customized in terms of battery savings. Whenever experiencing issues, you should carefully review them. This also applies to OOP, WatchDrip+ (if used) and Bluetooth.</p><div class="warning custom-block"><p class="custom-block-title">Android upgrades and updates</p><p>Updates and upgrades might reset these settings to default, always double-check afterwards.</p></div><h4 id="android-10" tabindex="-1">Android 10 <a class="header-anchor" href="#android-10" aria-label="Permalink to &quot;Android 10&quot;">​</a></h4><img src="'+a+'" style="zoom:75%;"><h4 id="android-11-and-above" tabindex="-1">Android 11 and above <a class="header-anchor" href="#android-11-and-above" aria-label="Permalink to &quot;Android 11 and above&quot;">​</a></h4><img src="'+i+'" style="zoom:75%;"><p>xDrip should run unrestricted.</p><img src="'+s+'" style="zoom:75%;"><h3 id="bluetooth" tabindex="-1">Bluetooth <a class="header-anchor" href="#bluetooth" aria-label="Permalink to &quot;Bluetooth&quot;">​</a></h3><p>You will most probably find Bluetooth in System app (three dots menu).<br> Some Android phones don&#39;t show the Bluetooth app.</p><img src="'+n+'" style="zoom:75%;"><p>Bluetooth should run unrestricted if xDrip connects directly to a sensor.</p><h2 id="xiaomi-miui-optimizations" tabindex="-1">Xiaomi MIUI Optimizations <a class="header-anchor" href="#xiaomi-miui-optimizations" aria-label="Permalink to &quot;Xiaomi MIUI Optimizations&quot;">​</a></h2><p>The MIUI Optimizations can have a massive impact (in a negative sense) on the stability of the system and the reliability of xDrip. If you experience an increased number of &quot;missed readings&quot; in MIUI 14 (or possibly earlier MIUI versions), you should try to deactivate the MIUI Optimizations. This setting can be found in the &amp;lt;Developer Options&gt;, which are hidden by default. The following describes how to display the &amp;lt;Developer Options&gt; and deactivate the MIUI Optimizations afterwards.</p><h3 id="enable-developer-options" tabindex="-1">Enable Developer Options <a class="header-anchor" href="#enable-developer-options" aria-label="Permalink to &quot;Enable Developer Options&quot;">​</a></h3><p>To show the <strong>&amp;lt;Developer Options&gt;</strong>, follow these steps:</p><ol><li>Open the <strong>&amp;lt;Settings&gt;</strong> of your smartphone.</li><li>Select <strong>&amp;lt;About phone&gt;</strong>.</li><li>Click 7 times on <strong>&amp;lt;MIUI version&gt;</strong> (first entry of the list).</li><li>A message <strong>&amp;lt;Now you are a developer.&gt;</strong> is shown.</li><li>Now the entry <strong>&amp;lt;Settings&gt;</strong> -&gt; <strong>&amp;lt;Additional settings&gt;</strong> -&gt; <strong>&amp;lt;Developer options&gt;</strong> is visible.</li></ol><h3 id="disable-xiaomi-miui-optimizations" tabindex="-1">Disable Xiaomi MIUI Optimizations <a class="header-anchor" href="#disable-xiaomi-miui-optimizations" aria-label="Permalink to &quot;Disable Xiaomi MIUI Optimizations&quot;">​</a></h3><p>To disable the MIUI Optimizations, you have to <strong>Enable Developer Options</strong> first. Then follow these steps:</p><ol><li>Open the <strong>&amp;lt;Settings&gt;</strong> of your smartphone.</li><li>Select <strong>&amp;lt;Additional settings&gt;</strong> -&gt; <strong>&amp;lt;Developer options&gt;</strong>.</li><li><strong>Only for MIUI 14:</strong> On MIUI 14, the <strong>&amp;lt;Turn on MIUI optimisation&gt;</strong> option is <strong>NOT</strong> visible by default. To see the missing option, scroll down to <strong>&amp;lt;AUTO-FILL&gt;</strong> and tap <strong>&amp;lt;Reset to default values&gt;</strong> multiple times. Then the required option will appear.</li><li><strong>Disable</strong> the option <strong>&amp;lt;Turn on MIUI optimisation&gt;</strong>!</li><li>Restart your smartphone.</li></ol><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.02.26" target="_blank" rel="noreferrer"><em>Last modified 6/03/2024</em></a></p>',30)])])}const I=r(h,[["render",m]]);export{_ as __pageData,I as default};
